function readFile(file){return new Promise((resolve,reject)=>{if(!file)return resolve("");const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=reject;r.readAsDataURL(file)})}
function imageToPng(data,maxWidth=900,maxHeight=450){if(!data)return Promise.resolve("");return new Promise(resolve=>{const image=new Image();image.onload=()=>{try{const scale=Math.min(1,maxWidth/(image.naturalWidth||maxWidth),maxHeight/(image.naturalHeight||maxHeight)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round((image.naturalWidth||maxWidth)*scale));canvas.height=Math.max(1,Math.round((image.naturalHeight||maxHeight)*scale));canvas.getContext("2d").drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL("image/png"))}catch{resolve(data)}};image.onerror=()=>resolve(data);image.src=data})}
async function readImageFile(file,maxWidth,maxHeight){return imageToPng(await readFile(file),maxWidth,maxHeight)}
function bindSettings(){const form=$("#settingsForm");enhanceMobileForms(form);updateAccountHint(form);form?.elements?.iban?.addEventListener("input",()=>updateAccountHint(form));form?.elements?.account_country?.addEventListener("change",()=>updateAccountHint(form));form?.addEventListener("submit",async e=>{e.preventDefault();if(form.dataset.submitting==="true")return;setFormBusy(form,true);try{const f=e.currentTarget,p=Object.fromEntries(new FormData(f));p.iban=storeAccount(p.iban,p.account_country);if(p.iban&&!paymentIban(p.iban,p.account_country)){notify(qrIssueText("account"),5600);f.elements.iban.focus();return}delete p.account_country;p.logo_data=await readImageFile(f.elements.logo_file.files[0],900,360)||state.profile?.logo_data||"";p.stamp_data=await readImageFile(f.elements.stamp_file.files[0],900,500)||state.profile?.stamp_data||"";delete p.logo_file;delete p.stamp_file;state.profile={...state.profile,...p};localStorage.setItem(localKey("profile"),JSON.stringify(state.profile));let remoteError=null;try{if(state.session&&!navigator.onLine)throw new Error("offline");if(state.session&&supabaseClient){const {error}=await supabaseClient.from("profiles").upsert({id:state.session.user.id,...p});if(error)throw error}}catch(error){remoteError=error;console.error(error);if(state.session)queueMutation({table:"profiles",id:state.session.user.id,kind:"upsert",mode:"upsert",payload:p})}renderUser();notify(remoteError?schemaNotice(remoteError):t("saved"))}finally{if(form.isConnected)setFormBusy(form,false)}})}
function invoiceDocument(inv,items){const p=profileData(),storedAccount=inv.iban||p.iban||"",meta=paymentMeta(inv),account=meta.iban||paymentIban(storedAccount),accountDisplay=displayAccount(storedAccount),qrName=meta.format==="pay"?"PAY by square":"QR Platba";return `<article class="invoice-paper" id="invoiceDocument"><header class="invoice-paper-head"><div>${p.logo_data?`<img class="invoice-logo" src="${esc(p.logo_data)}" alt="Logo">`:""}<span>${esc([p.address,p.zip,p.city,p.country].filter(Boolean).join(", "))}</span><span>${esc([p.ico&&`IČO: ${p.ico}`,p.dic&&`DIČ: ${p.dic}`,p.ic_dph&&`IČ DPH: ${p.ic_dph}`].filter(Boolean).join(" · "))}</span></div><div class="invoice-paper-meta"><span>FAKTÚRA</span><strong>${esc(inv.number)}</strong><small>Vystavená ${displayDate(inv.issued_on)}</small><small>Splatná ${displayDate(inv.due_on)}</small></div></header><div class="invoice-parties"><div><small>DODÁVATEĽ</small><strong>${esc(p.company_name||"")}</strong><span>${esc(p.email||"")}</span><span>${esc(accountDisplay)}</span></div><div><small>ODBERATEĽ</small><strong>${esc(inv.customer)}</strong><span>${esc(inv.customer_email||"")}</span></div></div><table class="invoice-paper-table"><thead><tr><th>Popis</th><th>Množstvo</th><th>Jednotka</th><th>Cena</th><th>Spolu</th></tr></thead><tbody>${items.map(x=>`<tr><td data-label="Popis">${esc(x.description)}</td><td data-label="Množstvo">${esc(x.quantity)}</td><td data-label="Jednotka">${esc(x.unit)}</td><td data-label="Cena">${money(x.unit_price,inv.currency)}</td><td data-label="Spolu">${money(x.total,inv.currency)}</td></tr>`).join("")}</tbody></table><div class="invoice-paper-bottom"><div class="invoice-payment"><strong>Platobné údaje</strong><span>Variabilný symbol: ${esc(inv.variable_symbol||inv.number)}</span><span>Účet: ${esc(accountDisplay||"neuvedené")}</span><span>IBAN: ${esc(account||"neuvedené")}</span>${inv.note?`<span>${esc(inv.note)}</span>`:""}</div><div class="invoice-sums"><span>Medzisúčet <strong>${money(inv.subtotal||inv.amount,inv.currency)}</strong></span><span>DPH ${esc(inv.vat_rate||0)} % <strong>${money(inv.vat_amount||0,inv.currency)}</strong></span><b>Celkom <strong>${money(inv.amount,inv.currency)}</strong></b></div>${inv.qr_enabled!==false?`<div class="invoice-qr" id="invoiceQr"><span>${qrName}</span></div>`:""}</div>${p.stamp_data?`<img class="invoice-stamp" src="${esc(p.stamp_data)}" alt="Pečiatka">`:""}</article>`}
async function openInvoiceDetail(id){const inv=state.invoices.find(x=>String(x.id)===String(id));if(!inv)return;state.activeInvoice=inv;const items=(await query("invoice_items")).filter(x=>String(x.invoice_id)===String(inv.id)),page=$(".page");requestAnimationFrame(animateAppView);const isLate=inv.status==="late"||(inv.due_on&&new Date(`${inv.due_on}T12:00:00`)<new Date(`${today()}T12:00:00`));page.innerHTML=pageHead("Faktúra",inv.number,`${inv.customer} · ${money(inv.amount,inv.currency)}`,`<button class="btn btn-light" data-back-invoices>${t("back")}</button><button class="btn btn-light" data-edit-detail>Upraviť</button><button class="btn btn-light" data-email-detail>${t("email")}</button><button class="btn btn-light" data-copy-link-detail>${t("copyLink")}</button>${isLate&&inv.customer_email?`<button class="btn btn-light" data-remind-detail>${t("remind")}</button>`:""}<button class="btn btn-primary" data-pdf-detail>${t("pdf")}</button>`)+`<div class="invoice-detail-grid"><section>${invoiceDocument(inv,items)}</section><aside class="detail-side panel"><h2>Stav faktúry</h2><label class="field">Stav<select id="detailStatus"><option value="draft" ${inv.status==="draft"?"selected":""}>Koncept</option><option value="waiting" ${inv.status==="waiting"?"selected":""}>Čaká na úhradu</option><option value="paid" ${inv.status==="paid"?"selected":""}>Uhradená</option><option value="late" ${inv.status==="late"?"selected":""}>Po splatnosti</option></select></label><p class="detail-note">Vystav overí účet a automaticky použije českú QR Platbu alebo slovenský PAY by square.</p><div class="detail-meta"><span>Vystavená<strong>${displayDate(inv.issued_on)}</strong></span><span>Splatná<strong>${displayDate(inv.due_on)}</strong></span><span>Variabilný symbol<strong>${esc(inv.variable_symbol||inv.number)}</strong></span>${inv.reminder_sent_at?`<span>${t("reminderSent")}<strong>${displayDate(inv.reminder_sent_at)}</strong></span>`:""}</div></aside></div>`;localizeDom();$("[data-back-invoices]",page).onclick=()=>renderView("invoices");$("[data-edit-detail]",page).onclick=()=>openDialog(inv.id);$("[data-remind-detail]",page)?.addEventListener("click",()=>openInvoiceEmailDialog(inv,"reminder"));$("[data-email-detail]",page).onclick=()=>openInvoiceEmailDialog(inv,"invoice");$("[data-copy-link-detail]",page)?.addEventListener("click",()=>copyPublicInvoiceLink(inv));$("[data-pdf-detail]",page).onclick=()=>downloadInvoicePdf(inv.id);$("[data-delete-detail]",page).onclick=()=>removeRecord("invoices",inv.id);$("#detailStatus",page).onchange=()=>updateInvoiceStatus(inv.id,$("#detailStatus",page).value);const qr=await qrData(inv),slot=$("#invoiceQr",page),meta=paymentMeta(inv),qrName=meta.format==="pay"?"PAY by square":"QR Platba";if(slot)slot.innerHTML=qr?'<img src="'+esc(qr)+'" alt="'+qrName+'"><span>'+qrName+'</span>':'<span class="qr-error">'+esc(qrIssueText(qrLastIssue||meta.code))+'</span>'}
async function updateInvoiceStatus(id,status){const inv=state.invoices.find(x=>String(x.id)===String(id));if(!inv)return;inv.status=status;let remoteError=null;try{if(state.session&&!navigator.onLine)throw new Error("offline");if(state.session&&supabaseClient){const {error}=await supabaseClient.from("invoices").update({status}).eq("id",id);if(error)throw error}}catch(error){remoteError=error;console.error(error);if(state.session)queueMutation({table:"invoices",id,kind:"upsert",mode:"update",payload:{status}})}upsertLocal("invoices",inv);syncNotificationIndicatorV5();notify(remoteError?schemaNotice(remoteError):t("saved"));openInvoiceDetail(id)}
const plain=v=>String(v??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"");
function drawPdfQr(pdf,model,x,y,size){const count=model.getModuleCount(),quiet=4,cell=size/(count+quiet*2);pdf.setFillColor(255,255,255);pdf.rect(x,y,size,size,"F");pdf.setFillColor(0,0,0);for(let row=0;row<count;row++)for(let col=0;col<count;col++)if(model.isDark(row,col))pdf.rect(x+(col+quiet)*cell,y+(row+quiet)*cell,cell+.03,cell+.03,"F")}
async function downloadInvoicePdf(id){
  const inv=typeof id==="object"?id:state.invoices.find(x=>String(x.id)===String(id));
  if(!inv)return;
  const items=(await query("invoice_items")).filter(x=>String(x.invoice_id)===String(inv.id));
  if(!window.jspdf?.jsPDF){notify("PDF modul sa nenačítal. Použi tlač v prehliadači.");window.print();return}
  const {jsPDF}=window.jspdf,pdf=new jsPDF({unit:"mm",format:"a4",compress:true}),p=profileData();
  const W=210,L=18,R=192,CW=174,ink=[16,24,40],muted=[93,105,124],rule=[218,225,235],soft=[246,248,252],accent=[29,78,216],white=[255,255,255];
  let pdfFont="helvetica",unicodePdf=false;
  try{const fonts=window.VYSTAV_PDF_FONTS;if(fonts?.regular&&fonts?.bold){pdf.addFileToVFS("VystavSans-Regular.ttf",fonts.regular);pdf.addFont("VystavSans-Regular.ttf","VystavSans","normal");pdf.addFileToVFS("VystavSans-Bold.ttf",fonts.bold);pdf.addFont("VystavSans-Bold.ttf","VystavSans","bold");pdfFont="VystavSans";unicodePdf=true}}catch(error){console.error("pdf font",error)}
  const pdfValue=v=>unicodePdf?String(v??""):plain(v);
  const cz=state.locale==="CZ";
  const label=cz?{
    invoice:"FAKTURA",supplier:"DODAVATEL",customer:"ODBĚRATEL",issued:"Datum vystavení",due:"Datum splatnosti",description:"Popis",quantity:"Množství",unitPrice:"Cena za jednotku",lineTotal:"Celkem",subtotal:"Mezisoučet",vat:"DPH",grandTotal:"CELKEM K ÚHRADĚ",payment:"PLATEBNÍ ÚDAJE",account:"Účet / IBAN",variable:"Variabilní symbol",amount:"Částka",scan:"Naskenujte v bankovní aplikaci",note:"Poznámka",noItems:"Faktura neobsahuje položky",paid:"UHRAZENO",late:"PO SPLATNOSTI",waiting:"ČEKÁ NA ÚHRADU",page:"Strana"
  }:{
    invoice:"FAKTÚRA",supplier:"DODÁVATEĽ",customer:"ODBERATEĽ",issued:"Dátum vystavenia",due:"Dátum splatnosti",description:"Popis",quantity:"Množstvo",unitPrice:"Cena za jednotku",lineTotal:"Spolu",subtotal:"Medzisúčet",vat:"DPH",grandTotal:"CELKOM NA ÚHRADU",payment:"PLATOBNÉ ÚDAJE",account:"Účet / IBAN",variable:"Variabilný symbol",amount:"Suma",scan:"Naskenujte v bankovej aplikácii",note:"Poznámka",noItems:"Faktúra neobsahuje položky",paid:"UHRADENÁ",late:"PO SPLATNOSTI",waiting:"ČAKÁ NA ÚHRADU",page:"Strana"
  };
  const setColor=color=>pdf.setTextColor(...color);
  const write=(value,x,y,size=9,style="normal",options={})=>{
    pdf.setFont(pdfFont,style==="bold"?"bold":"normal");pdf.setFontSize(size);setColor(options.color||ink);
    const valueText=pdfValue(value),lines=options.maxWidth?pdf.splitTextToSize(valueText,options.maxWidth):valueText;
    pdf.text(lines,x,y,{align:options.align||"left",baseline:"alphabetic"});
    return Array.isArray(lines)?lines.length:1;
  };
  const fitImage=(data,x,y,maxW,maxH)=>{
    if(!data)return false;
    try{const props=pdf.getImageProperties(data),scale=Math.min(maxW/props.width,maxH/props.height);pdf.addImage(data,"PNG",x,y,props.width*scale,props.height*scale);return true}catch(error){console.error("pdf image",error);return false}
  };
  const brandMark=(x=L,y=15,size=13)=>{
    if(fitImage(window.VYSTAV_BRAND_ICON,x,y,size,size))return;
    pdf.setFillColor(...accent);pdf.roundedRect(x,y,size,size,2.5,2.5,"F");
    write("V",x+size/2,y+size*.69,size*.62,"bold",{align:"center",color:white});
  };
  const statusText=inv.status==="paid"?label.paid:inv.status==="late"?label.late:label.waiting;
  const statusColors=inv.status==="paid"?{fill:[234,247,241],text:[21,118,83]}:inv.status==="late"?{fill:[255,240,237],text:[180,35,24]}:{fill:[255,244,223],text:[160,98,11]};
  const drawPageHeader=(continued=false)=>{
    pdf.setFillColor(...accent);pdf.rect(0,0,W,3,"F");
    if(continued){write(label.invoice+" "+inv.number,L,16,9,"bold");pdf.setDrawColor(...rule);pdf.line(L,21,R,21);return 29}
    return 0;
  };
  drawPageHeader();
  brandMark(L,15,13);
  const logo=await imageToPng(p.logo_data,1200,500);
  fitImage(logo,L+21,14,36,17);
  write(label.invoice,R,16,8,"bold",{align:"right",color:muted});
  write(inv.number,R,26,19,"bold",{align:"right"});
  const pillW=Math.max(30,pdf.getTextWidth(pdfValue(statusText))+10);
  pdf.setFillColor(...statusColors.fill);pdf.roundedRect(R-pillW,31,pillW,8,4,4,"F");
  write(statusText,R-pillW/2,36.3,7.5,"bold",{align:"center",color:statusColors.text});
  write(label.issued,118,17,7.5,"normal",{color:muted});write(displayDate(inv.issued_on||inv.issued),118,22.5,9,"bold");
  write(label.due,118,31,7.5,"normal",{color:muted});write(displayDate(inv.due_on||inv.due),118,36.5,9,"bold");
  pdf.setDrawColor(...rule);pdf.setLineWidth(.35);pdf.line(L,46,R,46);
  write(label.supplier,L,56,7.5,"bold",{color:accent});write(label.customer,108,56,7.5,"bold",{color:accent});
  let supplierY=64,customerY=64;
  if(p.company_name)supplierY+=write(p.company_name,L,supplierY,11,"bold",{maxWidth:76})*4.5;
  const supplierLines=[
    [p.address,p.zip,p.city].filter(Boolean).join(", "),
    p.country,
    p.ico?"IČO: "+p.ico:"",
    p.dic?"DIČ: "+p.dic:"",
    p.ic_dph?"IČ DPH: "+p.ic_dph:"",
    p.email||state.session?.user?.email||"",
    p.phone||""
  ].filter(Boolean);
  supplierLines.forEach(line=>{supplierY+=write(line,L,supplierY,8.3,"normal",{color:muted,maxWidth:76})*4.1});
  customerY+=write(inv.customer||"",108,customerY,11,"bold",{maxWidth:76})*4.5;
  const customerRecord=state.clients.find(x=>String(x.id)===String(inv.client_id)||String(x.name).toLowerCase()===String(inv.customer||"").toLowerCase())||{};
  const customerLines=[
    [customerRecord.address,customerRecord.zip,customerRecord.city].filter(Boolean).join(", "),
    customerRecord.country||"",
    customerRecord.ico?"IČO: "+customerRecord.ico:"",
    customerRecord.dic?"DIČ: "+customerRecord.dic:"",
    customerRecord.ic_dph?"IČ DPH: "+customerRecord.ic_dph:"",
    inv.customer_email||customerRecord.email||""
  ].filter(Boolean);
  customerLines.forEach(line=>{customerY+=write(line,108,customerY,8.3,"normal",{color:muted,maxWidth:76})*4.1});
  let y=Math.max(98,supplierY+5,customerY+5);
  if(y>205){pdf.addPage();y=drawPageHeader(true)}
  const drawTableHeader=()=>{
    pdf.setFillColor(...soft);pdf.roundedRect(L,y,CW,10,2,2,"F");
    write(label.description,L+4,y+6.4,7.6,"bold",{color:muted});
    write(label.quantity,124,y+6.4,7.6,"bold",{align:"right",color:muted});
    write(label.unitPrice,157,y+6.4,7.6,"bold",{align:"right",color:muted});
    write(label.lineTotal,R-3,y+6.4,7.6,"bold",{align:"right",color:muted});
    y+=14;
  };
  const newItemsPage=()=>{pdf.addPage();y=drawPageHeader(true);drawTableHeader()};
  drawTableHeader();
  const printableItems=items.length?items:[{description:label.noItems,quantity:"",unit_price:"",total:""}];
  printableItems.forEach((item,index)=>{
    const desc=pdf.splitTextToSize(plain(item.description||label.noItems),82),rowH=Math.max(11,desc.length*4.2+5);
    if(y+rowH>222)newItemsPage();
    if(index%2===1){pdf.setFillColor(251,252,254);pdf.rect(L,y-3,CW,rowH,"F")}
    write(item.description||label.noItems,L+4,y+2,8.8,"normal",{maxWidth:82});
    if(item.quantity!=="")write(String(item.quantity),124,y+2,8.8,"normal",{align:"right"});
    if(item.unit_price!=="")write(money(item.unit_price,inv.currency),157,y+2,8.8,"normal",{align:"right"});
    if(item.total!=="")write(money(item.total,inv.currency),R-3,y+2,8.8,"bold",{align:"right"});
    pdf.setDrawColor(...rule);pdf.line(L,y+rowH-3,R,y+rowH-3);y+=rowH;
  });
  if(y>205){pdf.addPage();y=drawPageHeader(true)}
  const totalsY=y+7,totalsX=111,totalsW=81;
  pdf.setFillColor(...soft);pdf.roundedRect(totalsX,totalsY,totalsW,31,3,3,"F");
  write(label.subtotal,totalsX+5,totalsY+7,8.3,"normal",{color:muted});
  write(money(inv.subtotal??inv.amount,inv.currency),R-5,totalsY+7,8.5,"bold",{align:"right"});
  write(label.vat+" "+Number(inv.vat_rate||0)+" %",totalsX+5,totalsY+14,8.3,"normal",{color:muted});
  write(money(inv.vat_amount||0,inv.currency),R-5,totalsY+14,8.5,"bold",{align:"right"});
  pdf.setFillColor(...accent);pdf.roundedRect(totalsX,totalsY+19,totalsW,12,3,3,"F");
  write(label.grandTotal,totalsX+5,totalsY+26.8,8.2,"bold",{color:white});
  write(money(inv.amount,inv.currency),R-5,totalsY+27,12,"bold",{align:"right",color:white});
  const account=paymentIban(inv.iban||p.iban);
  const showPayment=Boolean(account||inv.variable_symbol||inv.qr_enabled!==false);
  let paymentY=totalsY+40;
  if(showPayment){
    if(paymentY+67>271){pdf.addPage();paymentY=drawPageHeader(true)}
    pdf.setDrawColor(...rule);pdf.setFillColor(...white);pdf.roundedRect(L,paymentY,CW,62,4,4,"FD");
    write(label.payment,L+6,paymentY+9,8,"bold",{color:accent});
    let infoX=L+6;
    let model=null;
    if(inv.qr_enabled!==false)model=await qrMatrix(inv);
    if(model){drawPdfQr(pdf,model,L+7,paymentY+14,36);write(label.scan,L+25,paymentY+56,6.8,"normal",{align:"center",color:muted,maxWidth:44});infoX=L+50}
    else if(inv.qr_enabled!==false)notify(qrIssueText(qrLastIssue||paymentMeta(inv).code),5600);
    const valueX=R-6,labelX=infoX;
    write(label.account,labelX,paymentY+18,7.5,"normal",{color:muted});
    write(account||"-",valueX,paymentY+18,8.5,"bold",{align:"right",maxWidth:Math.max(48,valueX-labelX-28)});
    write(label.variable,labelX,paymentY+29,7.5,"normal",{color:muted});
    write(inv.variable_symbol||inv.number,valueX,paymentY+29,9,"bold",{align:"right"});
    write(label.amount,labelX,paymentY+40,7.5,"normal",{color:muted});
    write(money(inv.amount,inv.currency),valueX,paymentY+40,10.5,"bold",{align:"right"});
    write(label.due,labelX,paymentY+49,7.5,"normal",{color:muted});
    write(displayDate(inv.due_on||inv.due),valueX,paymentY+49,8.5,"bold",{align:"right"});
    paymentY+=68;
  }
  if(inv.note){
    if(paymentY+24>272){pdf.addPage();paymentY=drawPageHeader(true)}
    write(label.note,L,paymentY+2,7.5,"bold",{color:muted});
    const noteLines=pdf.splitTextToSize(plain(inv.note),116);
    write(inv.note,L,paymentY+8,8.5,"normal",{maxWidth:116,color:ink});
    paymentY+=noteLines.length*4.2+10;
  }
  const stamp=await imageToPng(p.stamp_data,1000,600);
  if(stamp&&paymentY<259)fitImage(stamp,145,paymentY,40,22);
  const pages=pdf.getNumberOfPages();
  for(let page=1;page<=pages;page++){
    pdf.setPage(page);pdf.setDrawColor(...rule);pdf.line(L,281,R,281);
    const footer=[p.email||state.session?.user?.email,p.website].filter(Boolean).join("  |  ");
    if(footer)write(footer,L,287,7.2,"normal",{color:muted,maxWidth:120});
    write(label.page+" "+page+" / "+pages,R,287,7.2,"normal",{align:"right",color:muted});
  }
  pdf.setProperties({title:label.invoice+" "+plain(inv.number),subject:label.invoice+" "+plain(inv.number)+" - "+plain(inv.customer),author:plain(p.company_name||p.full_name||""),creator:"Vystav"});
  pdf.save("faktura-"+plain(inv.number)+".pdf");
}
function exportRows(){return state.invoices.map(i=>({"Číslo faktúry":i.number,"Klient":i.customer,"E-mail":i.customer_email||"","Vystavená":i.issued_on||"","Splatnosť":i.due_on||"","Variabilný symbol":i.variable_symbol||i.number,"Medzisúčet":i.subtotal??i.amount,"DPH %":i.vat_rate||0,"DPH":i.vat_amount||0,"Celkom":i.amount,"Mena":i.currency||"EUR","Stav":i.status}))}
function downloadBlob(blob,name){const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
