function emailDialogMarkup(inv,kind){
  const cz=state.locale==="CZ",{subject,body}=kind==="invoice"?invoiceEmailTemplateDefaults(inv):reminderTemplateDefaults(inv),email=esc(inv.customer_email||"");
  const title=kind==="invoice"?(cz?"Odeslat fakturu":"Odoslať faktúru"):(cz?"Připomínka platby":"Pripomienka platby");
  const cta=kind==="invoice"?(cz?"Odeslat fakturu":"Odoslať faktúru"):(cz?"Odeslat připomínku":"Odoslať pripomienku");
  return `<section class="dialog" role="dialog" aria-modal="true" aria-labelledby="reminderDialogTitle"><header class="dialog-head"><div><h2 id="reminderDialogTitle">${title}</h2><p>${cz?`Odešle se na ${email}.`:`Odošle sa na ${email}.`}</p></div><button class="close-button" type="button" id="closeDialog" aria-label="Zavrieť">×</button></header><form id="reminderForm"><div class="form-body"><div class="form-grid"><div class="field full"><label>${cz?"Předmět":"Predmet"}<input name="subject" value="${esc(subject)}" required></label></div><div class="field full"><label>${cz?"Zpráva":"Správa"}<textarea name="body" rows="8" required>${esc(body)}</textarea></label></div><div class="field full"><label class="field-checkbox"><input type="checkbox" name="attach_pdf" checked> ${cz?"Přiložit PDF faktury":"Priložiť PDF faktúry"}</label></div></div></div><footer class="dialog-foot"><button class="btn btn-light" type="button" id="cancelDialog">${cz?"Zrušit":"Zrušiť"}</button><button class="btn btn-primary" type="submit">${cta}</button></footer></form></section>`
}
function openInvoiceEmailDialog(inv,kind="reminder"){
  if(!inv.customer_email){notify(t("reminderNoEmail"));return}
  dialog.innerHTML=emailDialogMarkup(inv,kind);presentDialog();localizeDom();
  $("#closeDialog",dialog).onclick=()=>closeDialog();
  $("#cancelDialog",dialog).onclick=()=>closeDialog();
  const form=$("#reminderForm",dialog);
  form.onsubmit=async event=>{
    event.preventDefault();
    if(form.dataset.submitting==="true")return;
    form.dataset.submitting="true";
    const submitButton=$('button[type="submit"]',form);if(submitButton)submitButton.disabled=true;
    try{
      await sendInvoiceEmail(inv,{kind,subject:form.elements.subject.value.trim(),body:form.elements.body.value.trim(),attachPdf:form.elements.attach_pdf.checked});
      closeDialog()
    }finally{form.dataset.submitting="false";if(submitButton)submitButton.disabled=false}
  };
  if(window.matchMedia("(pointer:fine)").matches)$("[name=subject]",dialog)?.focus()
}
async function sendInvoiceEmail(inv,overrides={}){
  const kind=overrides.kind==="invoice"?"invoice":"reminder";
  const sendingMsg=kind==="invoice"?t("emailSending"):t("reminderSending"),sentMsg=kind==="invoice"?t("emailSent"):t("reminderSent"),failedMsg=kind==="invoice"?t("emailFailed"):t("reminderFailed");
  if(!inv.customer_email){notify(t("reminderNoEmail"));return}
  notify(sendingMsg);
  try{
    const {data:sessionData}=await supabaseClient.auth.getSession();const token=sessionData?.session?.access_token;
    if(!token){notify(failedMsg);return}
    let pdfBase64=null;
    if(overrides.attachPdf!==false){try{const dataUri=await downloadInvoicePdf(inv,false);if(dataUri&&dataUri.includes("base64,"))pdfBase64=dataUri.split("base64,")[1]}catch(pdfError){console.error("invoice email pdf",pdfError)}}
    const res=await timedFetch(`${SUPABASE_URL}/functions/v1/send-reminder`,{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${token}`},body:JSON.stringify({invoiceId:inv.id,locale:state.locale,kind,pdfBase64,pdfFilename:`faktura-${plain(inv.number)}.pdf`,subject:overrides.subject||undefined,body:overrides.body||undefined})});
    const body=await res.json().catch(()=>({}));
    if(!res.ok){notify(body.error||failedMsg);return}
    if(kind==="reminder")inv.reminder_sent_at=body.sentAt;
    notify(sentMsg);
    if(state.activeInvoice&&String(state.activeInvoice.id)===String(inv.id))openInvoiceDetail(inv.id)
  }catch(e){notify(failedMsg)}
}
