      title:late?(cz?"Faktura je po splatnosti":"Faktúra je po splatnosti"):(days===0?(cz?"Faktura je splatná dnes":"Faktúra je splatná dnes"):(cz?"Blíží se splatnost":"Blíži sa splatnosť")),
