/* Backend reliability v6: authoritative sync, atomic invoices and honest errors. */
function reportBackendErrorV6(scope,error){
  var message=String(error?.message||error||""),fingerprint=`${scope}:${error?.code||""}:${message}`;
  console.error(`backend ${scope}`,error);
  updateNetworkState(isRetryableSyncError(error)?(navigator.onLine?"pending":"offline"):"pending");
  if(state.backendErrorFingerprint!==fingerprint){state.backendErrorFingerprint=fingerprint;notify(schemaNotice(error),5600)}
}
function pendingIdsV6(table){
  return new Set(readOutbox().filter(op=>op.table===table).map(op=>String(op.id)))
}
query=async function(table){
  var local=readLocal(table);
  if(!state.session||!supabaseClient)return local;
  try{
    var {data,error}=await supabaseClient.from(table).select("*").order("created_at",{ascending:false});
    if(error)throw error;
    var remote=data||[];
    if(table==="profiles")return remote;
    var key=item=>table==="invoice_items"?[item.invoice_id,item.description,item.quantity,item.unit,item.unit_price,item.total].join("|"):String(item.id);
    var merged=new Map(remote.map(item=>[key(item),item]));
    var pending=pendingIdsV6(table),pendingInvoices=table==="invoice_items"?pendingIdsV6("invoices"):new Set();
    local.forEach(item=>{if(pending.has(String(item.id))||pendingInvoices.has(String(item.invoice_id)))merged.set(key(item),{...merged.get(key(item)),...item})});
    var list=[...merged.values()].sort((a,b)=>String(b.created_at||"").localeCompare(String(a.created_at||"")));
    writeLocal(table,list);state.backendErrorFingerprint="";return list
  }catch(error){
    updateNetworkState(navigator.onLine?"pending":"offline");
    if(!isRetryableSyncError(error))throw error;
    console.error(`query ${table}`,error);return local
  }
};
saveInvoiceRemoteAtomic=async function(id,payload,items){
  if(!state.session||!supabaseClient)throw new Error("Authentication required");
  var {data,error}=await supabaseClient.rpc("save_invoice_with_items",{p_id:id,p_invoice:payload,p_items:items||[]});
  if(error)throw error;
  return data
};
flushOutbox=async function(){
  if(state.syncing||!navigator.onLine||!state.session||!supabaseClient)return;
  var queue=readOutbox();if(!queue.length){updateNetworkState("online");return}
  state.syncing=true;updateNetworkState("syncing");
  try{
    for(var op of [...queue]){
      if(op.kind==="delete"){
        var deletion=supabaseClient.from(op.table).delete().eq("id",op.id);
        if(op.table!=="profiles")deletion=deletion.eq("user_id",state.session.user.id);
        var deleted=await deletion;if(deleted.error)throw deleted.error
      }else if(op.table==="invoices"&&Array.isArray(op.items)){
        await saveInvoiceRemoteAtomic(op.id,op.payload,op.items)
      }else{
        var payload=op.table==="profiles"?{id:state.session.user.id,...op.payload}:{id:op.id,user_id:state.session.user.id,...op.payload};
        var request=op.mode==="update"?supabaseClient.from(op.table).update(op.payload).eq("id",op.id):supabaseClient.from(op.table).upsert(payload,{onConflict:"id"});
        if(op.mode==="update"&&op.table!=="profiles")request=request.eq("user_id",state.session.user.id);
        var result=await request;if(result.error)throw result.error
      }
      queue=readOutbox().filter(item=>!(mutationKey(item)===mutationKey(op)&&item.queued_at===op.queued_at));writeOutbox(queue)
    }
    state.backendErrorFingerprint="";updateNetworkState("online")
  }catch(error){reportBackendErrorV6("outbox",error)}finally{state.syncing=false}
};
saveRecord=async function(table,payload,id=null){
  var remoteError=null,remoteSaved=false,item={id:id||uuid(),...payload,created_at:new Date().toISOString()};
  try{
    if(state.session&&!navigator.onLine)throw new Error("offline");
    var saved=await saveRemote(table,payload,id);if(saved){item={...item,...saved};remoteSaved=true}
  }catch(error){
    remoteError=error;
    if(state.session&&isRetryableSyncError(error))queueMutation({table,id:item.id,kind:"upsert",mode:"upsert",payload});
    else if(state.session){reportBackendErrorV6(`save ${table}`,error);return}
  }
  upsertLocal(table,item);state[table]=remoteSaved?await query(table):readLocal(table);closeDialog();renderView(table);notify(remoteError?schemaNotice(remoteError):t("saved"))
};
removeRecord=async function(table,id){
  var message=state.locale==="CZ"?"Opravdu chcete tento záznam odstranit? Tuto akci nelze vrátit.":"Naozaj chcete tento záznam odstrániť? Túto akciu nemožno vrátiť.";
  if(!window.confirm(message))return;
  var remoteError=null,remoteSaved=false;
  try{
    if(state.session&&!navigator.onLine)throw new Error("offline");
    if(state.session&&supabaseClient){var request=supabaseClient.from(table).delete().eq("id",id);if(table!=="profiles")request=request.eq("user_id",state.session.user.id);var {error}=await request;if(error)throw error;remoteSaved=true}
  }catch(error){
    remoteError=error;
    if(state.session&&isRetryableSyncError(error))queueMutation({table,id,kind:"delete"});
    else if(state.session){reportBackendErrorV6(`delete ${table}`,error);return}
  }
  removeLocal(table,id);state[table]=remoteSaved?await query(table):readLocal(table);renderView(table==="invoices"?"invoices":table);notify(remoteError?schemaNotice(remoteError):t("deleted"))
};
updateInvoiceStatus=async function(id,status){
  var inv=state.invoices.find(x=>String(x.id)===String(id));if(!inv)return;
  var previous=inv.status,remoteError=null;
  try{
    if(state.session&&!navigator.onLine)throw new Error("offline");
    if(state.session&&supabaseClient){var {error}=await supabaseClient.from("invoices").update({status}).eq("id",id).eq("user_id",state.session.user.id);if(error)throw error}
  }catch(error){
    remoteError=error;
    if(state.session&&isRetryableSyncError(error))queueMutation({table:"invoices",id,kind:"upsert",mode:"update",payload:{status}});
    else if(state.session){inv.status=previous;reportBackendErrorV6("invoice status",error);return}
  }
  inv.status=status;upsertLocal("invoices",inv);syncNotificationIndicatorV5();notify(remoteError?schemaNotice(remoteError):t("saved"));openInvoiceDetail(id)
};
