/* Aging report + recurring-invoice nudge v7: pure client-side, no new backend calls. */
function agingBuckets(){
  const todayDate=new Date(`${today()}T12:00:00`),cz=state.locale==="CZ";
  const groups=[
    {key:"current",label:cz?"Do splatnosti":"Do splatnosti",items:[]},
    {key:"30",label:cz?"1–30 dní":"1–30 dní",items:[]},
    {key:"60",label:"31–60 dní",items:[]},
    {key:"90",label:cz?"60+ dní":"60+ dní",items:[]}
  ];
  state.invoices.filter(invoice=>invoice.status!=="paid").forEach(invoice=>{
    const due=dateInput(invoice.due_on||invoice.due),dueDate=new Date(`${due}T12:00:00`),daysOverdue=Math.floor((todayDate-dueDate)/86400000);
    const bucket=daysOverdue<0?groups[0]:daysOverdue<=30?groups[1]:daysOverdue<=60?groups[2]:groups[3];
    bucket.items.push(invoice)
  });
  return groups
}
function renderAgingPanel(){
  const grid=$("#agingGrid");if(!grid)return;
  const cz=state.locale==="CZ";
  grid.innerHTML=agingBuckets().map(group=>{
    const byCurrency={};
    group.items.forEach(invoice=>{const currency=invoice.currency||"EUR";byCurrency[currency]=(byCurrency[currency]||0)+Number(invoice.amount||0)});
    const amountText=Object.keys(byCurrency).length?Object.keys(byCurrency).map(currency=>money(byCurrency[currency],currency)).join(" + "):money(0);
    return `<div class="aging-bucket"><span>${esc(group.label)}</span><strong>${amountText}</strong><small>${group.items.length} ${cz?"faktur":"faktúr"}</small></div>`
  }).join("")
}
function recurringDueList(){
  const todayDate=new Date(`${today()}T12:00:00`);
  return state.invoices.filter(invoice=>{
    if(!invoice.is_recurring)return false;
    const issued=dateInput(invoice.issued_on||invoice.issued),issuedDate=new Date(`${issued}T12:00:00`),daysSince=Math.floor((todayDate-issuedDate)/86400000);
    if(daysSince<30)return false;
    return !state.invoices.some(other=>{
      if(String(other.id)===String(invoice.id))return false;
      const sameClient=invoice.client_id?String(other.client_id||"")===String(invoice.client_id):String(other.customer||"").toLowerCase()===String(invoice.customer||"").toLowerCase();
      return sameClient&&dateInput(other.issued_on||other.issued)>issued
    })
  })
}
function renderRecurringNudge(){
  const panel=$("#recurringPanel"),rows=$("#recurringRows");if(!panel||!rows)return;
  const list=recurringDueList();
  panel.hidden=!list.length;
  if(!list.length){rows.innerHTML="";return}
  const cz=state.locale==="CZ",label=cz?"Duplikovat":"Duplikovať";
  rows.innerHTML=list.map(invoice=>`<tr><td>${esc(invoice.number)}</td><td>${esc(invoice.customer)}</td><td>${displayDate(invoice.issued_on||invoice.issued)}</td><td class="row-actions"><button class="row-menu" data-duplicate-invoice="${esc(invoice.id)}" aria-label="${label}" title="${label}">${vIcon("copy")}</button></td></tr>`).join("");
  bindInvoiceRows(rows)
}
var baseRenderDashboardV7=renderDashboard;renderDashboard=function(){baseRenderDashboardV7();renderAgingPanel();renderRecurringNudge()};
async function renderPublicInvoice(token){
  const body=$("#publicInvoiceBody");if(!body)return;
  body.innerHTML='<p class="public-invoice-status">Načítavam faktúru…</p>';
  document.title="Vystav | Faktúra";
  try{
    if(!supabaseClient)throw new Error("offline");
    const {data,error}=await supabaseClient.rpc("get_public_invoice",{p_token:token});
    if(error)throw error;
    if(!data||!data.invoice){body.innerHTML='<p class="public-invoice-status">Faktúra sa nenašla. Skontroluj, či je odkaz správny.</p>';return}
    const inv=data.invoice,items=data.items||[],profile=data.profile||{};
    document.title=`Vystav | Faktúra ${inv.number||""}`;
    body.innerHTML=invoiceDocument(inv,items,profile);
    if(inv.qr_enabled!==false){
      const qr=await qrData(inv),slot=$("#invoiceQr",body),meta=paymentMeta(inv),qrName=meta.format==="pay"?"PAY by square":"QR Platba";
      if(slot)slot.innerHTML=qr?'<img src="'+esc(qr)+'" alt="'+qrName+'"><span>'+qrName+'</span>':'<span class="qr-error">'+esc(qrIssueText(qrLastIssue||meta.code))+'</span>'
    }
  }catch(error){
    console.error("public invoice",error);
    body.innerHTML='<p class="public-invoice-status">Faktúru sa nepodarilo načítať. Skús to znova o chvíľu.</p>'
  }
}
